class CircuitBreaker:
    def __init__(self, failure_rate_threshold: float, min_samples: int, recovery_timeout: float, half_open_success_needed: int):
        self.threshold = failure_rate_threshold
        self.min_samples = min_samples
        self.recovery_timeout = recovery_timeout
        self.half_open_needed = half_open_success_needed
        self._state = 'CLOSED'
        self.trip_time = 0.0
        self.samples = []
        self.half_open_successes = 0
        self.half_open_in_flight = 0

    @property
    def state(self) -> str:
        return self._state

    def allow_request(self, current_time: float) -> bool:
        if self._state == 'CLOSED':
            return True
        if self._state == 'OPEN':
            if current_time - self.trip_time >= self.recovery_timeout:
                self._state = 'HALF_OPEN'
                self.half_open_successes = 0
                self.half_open_in_flight = 1
                return True
            return False
        if self._state == 'HALF_OPEN':
            if self.half_open_in_flight < self.half_open_needed:
                self.half_open_in_flight += 1
                return True
            return False
        return False

    def record_result(self, success: bool, current_time: float):
        if self._state == 'CLOSED':
            self.samples.append(success)
            if len(self.samples) >= self.min_samples:
                failures = sum(1 for s in self.samples if not s)
                rate = (failures / len(self.samples)) * 100.0
                if rate >= self.threshold:
                    self._state = 'OPEN'
                    self.trip_time = current_time
                    self.samples = []
        elif self._state == 'HALF_OPEN':
            if success:
                self.half_open_successes += 1
                if self.half_open_successes >= self.half_open_needed:
                    self._state = 'CLOSED'
                    self.samples = []
                    self.half_open_in_flight = 0
                    self.half_open_successes = 0
            else:
                self._state = 'OPEN'
                self.trip_time = current_time
                self.half_open_in_flight = 0
                self.half_open_successes = 0
